      "rawText": "首页 > 科研进展 手性金属卤化物因其独特的手性与自旋特性备受关注。现有体系多采用手性有机阳离子引入手性，其种类有限，限制了材料组成、结构与功能的灵活性。金属卤化物还可通过构筑单元螺旋排列产生本征 手性 结构，但其结构—性能关系仍未被充分阐明，制约了手性光学性能的精确调控。因此，开发具备双色可调圆偏振发光特性的单组分金属卤化物，对先进光学和显示技术具有重要意义。 近日，中国科学院大连化学物理研究所研究团队在金属卤化物发光动力学研究中取得进展，揭示了不对称氢键网络对金属卤化物手性光学性质的调控作用，在有机—无机杂化锰卤化物中实现了绿—红双色可调的圆偏振发光。 研究团队采用非手性 4- 苄基哌啶阳",
