      "rawText": "首页 > 科研进展 长余辉发光是无需实时激发、可储存光能并缓慢释放光子的成像技术，成像信背比优异，但具有明确“分子结构—发光强度”关系、可用于高对比度激活型成像的有机长余辉分子仍然稀缺。 近日，中国科学院杭州医学研究所科研团队报道了全新的有机余辉发光分子平台——香豆素衍生物，筛选9种代表性香豆素分子，证实香豆素衍生物在光激发后能够产生明亮的长余辉发光。团队还揭示了其构效关系：分子骨架的刚性是提升发光效率的关键，其中香豆素545具有相对最佳的长余辉性能。 基于香豆素分子，团队设计了过氧亚硝酸盐激活型长余辉探针C545-MP NPs，实现了溃疡性结肠炎和帕金森病小鼠模型中病变区域的精准成像与疗效评",
